import{_ as r,C as a,o as l,c as s,j as t,a as d,G as o,a7 as c}from"./chunks/framework.BvFspj3b.js";const w=JSON.parse(`{"title":"Instruction Manual","description":"ICC-CE's three working modes, interface layout, toolbar features, and daily usage scenarios","frontmatter":{"title":"Instruction Manual","description":"ICC-CE's three working modes, interface layout, toolbar features, and daily usage scenarios"},"headers":[],"relativePath":"en/guide/instruction-manual.md","filePath":"en/guide/instruction-manual.md"}`),h={name:"en/guide/instruction-manual.md"};function u(m,e,p,g,b,f){const n=a("ArticleMetadata"),i=a("KnownBugs");return l(),s("div",null,[e[0]||(e[0]=t("h1",{id:"instruction-manual",tabindex:"-1"},[d("Instruction Manual "),t("a",{class:"header-anchor",href:"#instruction-manual","aria-label":'Permalink to "Instruction Manual"'},"​")],-1)),o(n),o(i),e[1]||(e[1]=c('<h2 id="three-working-modes" tabindex="-1">Three Working Modes <a class="header-anchor" href="#three-working-modes" aria-label="Permalink to &quot;Three Working Modes&quot;">​</a></h2><p>ICC-CE provides three core working modes, switchable via the mode button on the toolbar:</p><h3 id="screen-annotation-mode-default" tabindex="-1">Screen Annotation Mode (Default) <a class="header-anchor" href="#screen-annotation-mode-default" aria-label="Permalink to &quot;Screen Annotation Mode (Default)&quot;">​</a></h3><p>Overlays a transparent canvas on top of the screen, allowing you to write and annotate over any software interface.</p><ul><li>Ideal for real-time annotations on PPT, PDF, browser, video players, etc.</li><li>Toolbar floats on the screen edge for quick tool switching</li><li>Supports ink saving, screenshots, undo/redo, and more</li></ul><h3 id="whiteboard-mode" tabindex="-1">Whiteboard Mode <a class="header-anchor" href="#whiteboard-mode" aria-label="Permalink to &quot;Whiteboard Mode&quot;">​</a></h3><p>Full-screen solid background, functioning as an electronic whiteboard.</p><ul><li>Full-screen writing space, perfect for classroom board writing</li><li>Supports image insertion, background grid</li><li>Toolbar is positioned on both sides of the screen, providing more writing tools</li><li>Supports extended canvas for unlimited writing space</li></ul><h3 id="mouse-mode" tabindex="-1">Mouse Mode <a class="header-anchor" href="#mouse-mode" aria-label="Permalink to &quot;Mouse Mode&quot;">​</a></h3><p>Disables ink drawing, allowing the mouse to pass through to the underlying application for normal operation.</p><ul><li>Can be quickly toggled with Screen Annotation Mode</li><li>Suitable for scenarios where you frequently switch between writing and operating applications</li></ul><h2 id="interface-toolbar" tabindex="-1">Interface &amp; Toolbar <a class="header-anchor" href="#interface-toolbar" aria-label="Permalink to &quot;Interface &amp; Toolbar&quot;">​</a></h2><h3 id="toolbar-layout" tabindex="-1">Toolbar Layout <a class="header-anchor" href="#toolbar-layout" aria-label="Permalink to &quot;Toolbar Layout&quot;">​</a></h3><p>The toolbar floats by default on the right edge of the screen, mainly containing:</p><table tabindex="0"><thead><tr><th>Area</th><th>Function</th></tr></thead><tbody><tr><td>Pen Tools</td><td>Pen, highlighter, laser pointer, eraser</td></tr><tr><td>Color Selection</td><td>Quick color palette, custom colors</td></tr><tr><td>Width Adjustment</td><td>Stroke thickness slider</td></tr><tr><td>Mode Switch</td><td>Screen Annotation / Whiteboard / Mouse Mode</td></tr><tr><td>Toolbox</td><td>Settings, screenshot, clear screen, save, undo/redo</td></tr><tr><td>PPT Control</td><td>Page navigation, jump (appears automatically during slideshow)</td></tr></tbody></table><h3 id="toolbar-states" tabindex="-1">Toolbar States <a class="header-anchor" href="#toolbar-states" aria-label="Permalink to &quot;Toolbar States&quot;">​</a></h3><ul><li><strong>Expanded</strong>: Fully displays all tool buttons</li><li><strong>Collapsed</strong>: Shrinks to a thin strip on the screen edge; hover or click to expand</li><li><strong>Mini Bar</strong>: Automatically shrinks to a compact rounded mini toolbar after a period of inactivity (requires enabling in settings)</li></ul><h3 id="quick-panel" tabindex="-1">Quick Panel <a class="header-anchor" href="#quick-panel" aria-label="Permalink to &quot;Quick Panel&quot;">​</a></h3><p>In collapsed mode, a quick panel appears at the bottom of the screen, providing fast access to commonly used tools.</p><h2 id="daily-usage-scenarios" tabindex="-1">Daily Usage Scenarios <a class="header-anchor" href="#daily-usage-scenarios" aria-label="Permalink to &quot;Daily Usage Scenarios&quot;">​</a></h2><h3 id="classroom-teaching" tabindex="-1">Classroom Teaching <a class="header-anchor" href="#classroom-teaching" aria-label="Permalink to &quot;Classroom Teaching&quot;">​</a></h3><ol><li>Open PPT and start slideshow; ICC-CE automatically enters annotation mode</li><li>Use the pen to write key points on slides</li><li>Use the highlighter to emphasize important content</li><li>Ink is automatically saved when switching slides and restored when returning</li><li>Export annotated screenshots or time capsules after class</li></ol><h3 id="online-teaching" tabindex="-1">Online Teaching <a class="header-anchor" href="#online-teaching" aria-label="Permalink to &quot;Online Teaching&quot;">​</a></h3><ol><li>Use Screen Annotation Mode to annotate courseware or browser content in real-time</li><li>Combine with Whiteboard Mode for board writing explanations</li><li>Use the laser pointer to guide attention</li><li>Take screenshots to share lecture content with students</li></ol><h3 id="meeting-presentations" tabindex="-1">Meeting Presentations <a class="header-anchor" href="#meeting-presentations" aria-label="Permalink to &quot;Meeting Presentations&quot;">​</a></h3><ol><li>Annotate presentation documents in real-time</li><li>Use shape recognition to quickly draw standard graphics</li><li>Use two-finger zoom/pan to view details</li><li>Save ink files and screenshots for archiving after the meeting</li></ol><h3 id="daily-office-work" tabindex="-1">Daily Office Work <a class="header-anchor" href="#daily-office-work" aria-label="Permalink to &quot;Daily Office Work&quot;">​</a></h3><ol><li>Screenshot annotation: Capture screen content and add annotations</li><li>Document annotation: Write comments on PDFs or documents</li><li>Scratchpad: Quickly record ideas and sketches</li></ol>',28))])}const y=r(h,[["render",u]]);export{w as __pageData,y as default};
